-- Feedback development gates (Slice 2 of docs/blueprint/feedback/request-driven-development.md).
--
-- Additive only: one enum, one table (feedback.development) and one defaulted column on
-- feedback.feedback. Existing rows are untouched (development_attempts = 0); the application
-- before Slice 2 ignores all of it, so the order is: apply this, then ship (§R.8).
-- Generated by `bun run db:schema-diff` and checked by lifecycle-migration.pglite.test.ts,
-- which applies it after feedback-lifecycle.sql and compares the result with the Drizzle schema.
-- Apply with the cloud-db-change skill, on ApeDevil's word only, in one transaction.
-- If the deployment then fails, leave it in place: the previous application ignores it.

BEGIN;

CREATE TYPE "feedback"."feedback_release_verification" AS ENUM('live_version', 'maintainer');
CREATE TABLE "feedback"."development" (
	"feedback_id" text PRIMARY KEY NOT NULL,
	"branch" text NOT NULL,
	"attempt" integer NOT NULL,
	"scope" text NOT NULL,
	"include_submitter_text" boolean DEFAULT false NOT NULL,
	"approved_by" text NOT NULL,
	"approved_at" timestamp with time zone DEFAULT now() NOT NULL,
	"reported_sha" text,
	"report" jsonb,
	"reported_at" timestamp with time zone,
	"report_revision" integer DEFAULT 0 NOT NULL,
	"release_approved_sha" text,
	"release_approved_by" text,
	"release_approved_at" timestamp with time zone,
	"withdrawn_release_sha" text,
	"released_sha" text,
	"released_at" timestamp with time zone,
	"release_verification" "feedback"."feedback_release_verification",
	"running_sha_at_release" text,
	"receipt" jsonb,
	CONSTRAINT "development_branch_shape" CHECK ("feedback"."development"."branch" ~ '^[a-z]+/[a-z]+/[a-z0-9][a-z0-9-]{0,79}$'),
	CONSTRAINT "development_scope_len" CHECK (char_length("feedback"."development"."scope") BETWEEN 1 AND 8000),
	CONSTRAINT "development_reported_sha_shape" CHECK ("feedback"."development"."reported_sha" ~ '^[0-9a-f]{40}$'),
	CONSTRAINT "development_release_sha_shape" CHECK ("feedback"."development"."release_approved_sha" ~ '^[0-9a-f]{40}$'),
	CONSTRAINT "development_released_sha_shape" CHECK ("feedback"."development"."released_sha" ~ '^[0-9a-f]{40}$'),
	CONSTRAINT "development_withdrawn_sha_shape" CHECK ("feedback"."development"."withdrawn_release_sha" ~ '^[0-9a-f]{40}$'),
	CONSTRAINT "development_attempt_range" CHECK ("feedback"."development"."attempt" >= 1),
	CONSTRAINT "development_report_revision_range" CHECK ("feedback"."development"."report_revision" >= 0),
	CONSTRAINT "development_report_size" CHECK (octet_length("feedback"."development"."report"::text) <= 32000),
	CONSTRAINT "development_receipt_size" CHECK (octet_length("feedback"."development"."receipt"::text) <= 4000),
	CONSTRAINT "development_report_complete" CHECK (("feedback"."development"."reported_sha" IS NULL) = ("feedback"."development"."report" IS NULL) AND ("feedback"."development"."report" IS NULL) = ("feedback"."development"."reported_at" IS NULL)),
	CONSTRAINT "development_release_binds_report" CHECK ("feedback"."development"."release_approved_sha" IS NULL OR ("feedback"."development"."reported_sha" IS NOT NULL AND "feedback"."development"."release_approved_sha" = "feedback"."development"."reported_sha")),
	CONSTRAINT "development_released_after_approval" CHECK ("feedback"."development"."released_sha" IS NULL OR "feedback"."development"."release_approved_sha" IS NOT NULL)
);

ALTER TABLE "feedback"."feedback" ADD COLUMN "development_attempts" integer DEFAULT 0 NOT NULL;
ALTER TABLE "feedback"."development" ADD CONSTRAINT "development_feedback_id_feedback_id_fk" FOREIGN KEY ("feedback_id") REFERENCES "feedback"."feedback"("id") ON DELETE cascade ON UPDATE no action;
CREATE UNIQUE INDEX "development_branch_idx" ON "feedback"."development" USING btree ("branch");
ALTER TABLE "feedback"."feedback" ADD CONSTRAINT "feedback_development_attempts_range" CHECK ("feedback"."feedback"."development_attempts" >= 0);

COMMIT;
